  function buildTowersGeoJSON(raw){
    return {
      type: "FeatureCollection",
      features: raw.map(function(item){
        var floors = item[0];
        var ring = item[1];
        var color = item[2] || null;
        return {
          type: "Feature",
          properties: { floors: floors, height: floors * 3, color: color },
          geometry: { type: "Polygon", coordinates: [ring] }
        };
      })
    };
  }

  // ---- "줌아웃 해도 매스가 계속 보이게" 하기 위한 2단계(LOD) 처리 ----
  // 점(마커) 대신, 실제 건물 매스 자체가 줌아웃에서도 화면에서 완전히 사라지지 않도록,
  // 같은 건물을 "부풀린 버전(far)"과 "실제 크기 버전(near)"두 개의 레이어로 나눠서 그린다.
  // far 레이어는 zoom 0 ~ FAR_SWITCH_ZOOM 구간에서만 보이고, 그 지점을 넘어서면 near(실제 크기)로 자연스럽게 바뀐다.
  // (fill-extrusion은 지리적 좌표 그대로 그려지기 때문에 줌아웃하면 폭이 화면상 1픽셀 미만으로 줄어 안 보이게 되는데,
  //  이를 막으려면 "화면에 보이는 좌표 자체"를 줌 구간별로 다르게 만드는 수밖에 없다 — 이게 그 방법.)
  var FAR_SWITCH_ZOOM = 14;
  var FAR_MIN_SIZE_DEG = 0.0018; // 약 150~165m 최소 크기로 부풀림(대신 서로 가까운 건물들은 뭉쳐 보일 수 있음)

  function bboxOfRing(ring){
    var minLon = Infinity, maxLon = -Infinity, minLat = Infinity, maxLat = -Infinity;
    for (var i = 0; i < ring.length; i++) {
      var lon = ring[i][0], lat = ring[i][1];
      if (lon < minLon) minLon = lon; if (lon > maxLon) maxLon = lon;
      if (lat < minLat) minLat = lat; if (lat > maxLat) maxLat = lat;
    }
    return [minLon, minLat, maxLon, maxLat];
  }

  // 원래 건물 폭이 minSizeDeg보다 작으면, 중심은 그대로 두고 minSizeDeg 크기까지 사각형을 부풀린다.
  function inflateRingToMinSize(ring, minSizeDeg){
    var b = bboxOfRing(ring);
    var cx = (b[0] + b[2]) / 2, cy = (b[1] + b[3]) / 2;
    var halfW = Math.max(b[2] - b[0], minSizeDeg) / 2;
    var halfH = Math.max(b[3] - b[1], minSizeDeg) / 2;
    return [
      [cx - halfW, cy - halfH], [cx + halfW, cy - halfH],
      [cx + halfW, cy + halfH], [cx - halfW, cy + halfH],
      [cx - halfW, cy - halfH]
    ];
  }

  // far 레이어용 — raw 배열의 각 건물을 minSizeDeg 이상 크기로 부풀린 GeoJSON을 만든다.
  function buildTowersGeoJSONFar(raw, minSizeDeg){
    return {
      type: "FeatureCollection",
      features: raw.map(function(item){
        var floors = item[0];
        var ring = inflateRingToMinSize(item[1], minSizeDeg);
        var color = item[2] || null;
        return {
          type: "Feature",
          properties: { floors: floors, height: floors * 3, color: color },
          geometry: { type: "Polygon", coordinates: [ring] }
        };
      })
    };
  }

